(
    function(outputs, steps, params, stepResult, assertEqual) {
        var step3 = steps('0d61d5f31b5b86d89fde86acdd4bcb89');
        var recordId = step3.record_id;
        var outputMessage = '';
        var teleworkAgreement = new GlideRecord('x_hccc_hoc_ohs_telework_agreement')
        teleworkAgreement.get(recordId);

        // add test script here
        var telwrkUtils = new x_hccc_hoc_ohs.HoCOHSMTelWrkUtils();

        outputMessage = "recordId: " + recordId + "\r\nAgreement number: " + teleworkAgreement.number.toString();

